#!/usr/bin/env python3
# luxarch:fleet-start-after-compact hook v3 - DO NOT edit this file - it is emitted by `luxarch --emit hooks`; re-emit to update.
"""After any compaction, tell the agent to run `/fleet-start`; when it runs, tell the agent who it
is, where its owner order is, and the owner's notes of this session.

Claude Code compacts on its own (when the context fills, and while a session sits idle), so "the
owner runs /compact, then /fleet-start" does not describe every compact. The CLAUDE.md line asking
for `/fleet-start` after a compact only works if someone remembers it; this hook fires on the event.

The owner names each session for its job, `[<repo> <role>]` (`[shop mypy]`), and Claude Code
records that name in the session's transcript. An owner order is one of two things, both the
owner's own: a LuxPM issue the OWNER labelled `owner-order` (and `agent:<role>` for one role), or
the note of a `/fleet-start <note>` the owner typed. No agent adds the label; work a note names
that no open issue covers, the agent files itself, `in_progress`. So the context
this hook adds names the agent, its role, the exact LuxPM query for its labelled owner orders, the
query for the work other agents of the repo handed it (issues labelled `agent:<role>`, any state:
a request, or a reply it owes), and every `/fleet-start` note of this session verbatim
(`fleet-start-gate` records them), so a compact loses none of them.

SessionStart(compact): its stdout lands in the post-compaction context. UserPromptSubmit: when the
whole prompt is `/fleet-start` (plain or as Claude Code's tags), its stdout lands beside the skill;
a note after the command is the owner's instruction and go-ahead. Any other prompt adds nothing. A
hook cannot invoke a skill, so this is text the agent reads, not a call. Never blocks, never errors
out.
"""

from __future__ import annotations

import contextlib
import sys
from pathlib import Path

sys.path.insert(0, str(Path(__file__).parent))
from _ledger import (
    OWNER_ORDER_LABEL,
    agent_name,
    agent_role,
    event_cwd,
    owner_notes,
    read_event,
    repo_project,
    start_note,
    tree_dir,
)

_COMPACTED = (
    "This session was just compacted. Before anything else, run `/fleet-start`: re-read this "
    "repo's CLAUDE.md and the conduct standard's sections it names, and rehydrate from LuxPM. "
    "The summary above is not the state; LuxPM and the repo are. A compact is not a new start: "
    "the go-ahead this session already had stands, so after rehydrating carry on with your owner "
    "order without waiting. Only a `/fleet-start` the owner types with no note makes you wait "
    "for the owner's next message."
)
_UNREADABLE = (OSError, ValueError)


def _identity(ev: dict[str, object]) -> str:
    name = agent_name(str(ev.get("transcript_path") or ""))
    role = agent_role(name)
    try:
        project = repo_project(tree_dir()) or repo_project(event_cwd())
    except OSError:
        project = ""
    where = f'project="{project}", ' if project else ""
    if not name:
        who = (
            "This session has no name. The owner names each agent for its job, "
            "`[<repo> <role>]`; until it has one, your owner orders are the ones for every agent "
            "here."
        )
    elif not role:
        who = (
            f"You are `{name}`, with no role in the name: your owner orders are the ones for "
            "every agent here."
        )
    else:
        who = f"You are `{name}`, role `{role}`."
    queries = (
        f'luxpm_list_issues({where}labels=["{OWNER_ORDER_LABEL}", "agent:{role}"])'
        f' and luxpm_list_issues({where}labels=["{OWNER_ORDER_LABEL}"])'
        if role
        else f'luxpm_list_issues({where}labels=["{OWNER_ORDER_LABEL}"])'
    )
    handoffs = (
        f" Then the work other agents of this repo handed you: luxpm_list_issues({where}labels="
        f'["agent:{role}"]), every open one, backlog included, skipping an owner order (it also '
        "carries `owner-order`; its labels are the owner's): a request, or a reply you owe. Answer "
        "each before your own queue: do the step, then hand it back (the asker's `agent:` label in "
        f"place of `agent:{role}`, waiting_on naming the asker) or close it with waiting_on "
        f"cleared and `agent:{role}` dropped."
        if role
        else ""
    )
    return (
        f"{who} Your first LuxPM call is {queries}: an open owner order is your work, ahead of "
        "the open issues, the guard reds and every queue. Only work that blocks other agents now "
        "interrupts it, and you say so when it does. Only the owner labels, parks or cancels an "
        f"owner order.{handoffs}"
    )


def _notes(current: str = "") -> str:
    """Every `/fleet-start` note of this session, verbatim, with the one being typed now."""
    notes = [n["note"] for n in owner_notes()]
    if current and (not notes or notes[-1] != current):
        notes.append(current)
    if not notes:
        return ""
    listed = "".join(f"\n  {i}. {n}" for i, n in enumerate(notes, 1))
    return (
        "\nThe owner's orders this session, verbatim (each a `/fleet-start <note>` the owner "
        f"typed):{listed}\nRecord each one verbatim as an activity on the issue you work it in "
        "(luxpm_log_activity). Work a note names that no open issue covers, you file yourself "
        "(luxpm_create_issue in this repo's project, with a title, state in_progress, "
        "the note quoted), then start in its worktree; never ask the owner to file it."
    )


def _text(ev: dict[str, object]) -> str:
    if ev.get("hook_event_name") == "UserPromptSubmit":
        note = start_note(str(ev.get("prompt") or ""))
        if note is None:
            return ""
        then = (
            "The owner left a note with /fleet-start: it is your instruction and your go-ahead."
            if note
            else "No note came with /fleet-start: end it by stating your name, your owner order "
            "and your next step, and wait for the owner's next message before any other work."
        )
        return f"{_identity(ev)} {then}{_notes(note)}"
    return f"{_COMPACTED} {_identity(ev)}{_notes()}"


def main() -> int:
    # A reminder must never break a session: an unreadable payload or a closed stdout is not an
    # error worth surfacing.
    try:
        text = _text(read_event())
    except _UNREADABLE:
        text = (
            ""
            if read_event().get("hook_event_name") == "UserPromptSubmit"
            else _COMPACTED
        )
    with contextlib.suppress(OSError):
        if text:
            sys.stdout.write(text + "\n")
    return 0


sys.exit(main())
